import {createFeatures} from './features-ui.js';
import * as DB from './db.js';
import {esc,icon,btn,iconBtn,thumb,field,selectField,checkField,empty,toast,showDialog,closeDialog,safeError,download,compressImage,loadScript} from './ui.js';
import {openScanner,closeScanner} from './scanner.js';
import {csvExport,previewCSV,importCSV,validateBackup,restoreBackup,makeBackup,readLegacyBrowserBackup} from './transfer.js';
import {seedDemo} from './demo.js';
import {connectionDialog,initConnectionUI} from './repository-ui.js';
const $=s=>document.querySelector(s);
const features=createFeatures(()=>({data,settings,cart,demo,filters,limit,money,heading,metric,table,listFooter,searchInput,fmtDate,rangeDates,inRange,stats,dateControl,customRange,render,reload,refresh,confirmAction,printContent,saveDraft,navigate,setCart:v=>{cart=v;}}));
let data={},settings={...DB.defaults},cart=DB.newCart(),demo=sessionStorage.getItem('storeflow-github-demo')==='1',route='dashboard',filters={},limit=40,busy=false,range='7',customFrom='',customTo='',importRows=[],pendingBackup=null,productAfterSave=null,installEvent=null,draftTimer;
let channel;try{channel=new BroadcastChannel('storeflow:'+new URL('../../',import.meta.url).pathname);}catch{}
const money=(v=0)=>`${esc(settings.symbol)} ${Number(v/100).toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:2})}`;
const fmtDate=(s,withTime=false)=>new Date(s).toLocaleString(undefined,withTime?{month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit'}:{month:'short',day:'numeric'});
const products=()=>data.products.filter(p=>!p.deleted);
const product=id=>data.products.find(p=>p.id===id);
const lowProducts=()=>products().filter(p=>p.active&&p.stock<=p.minStock);
const currentTotals=()=>{try{return DB.totals(cart,data.products);}catch{return {subtotal:0,discount:0,tax:0,charges:0,total:0,cost:0,profit:0,lines:[]};}};
const nameOf=()=> 'Walk-in customer';
const searchProduct=(p,q)=>[p.name,p.sku,p.barcode,p.category,p.brand].join(' ').toLowerCase().includes(q.toLowerCase());
const profitPct=p=>p.price?((p.price-p.cost)/p.price*100).toFixed(1):'0.0';
const status=p=>!p.active?['Inactive','neutral']:p.expiry&&p.expiry<DB.today()?['Expired','danger']:p.stock<=0?['Out of stock','danger']:p.stock<=p.minStock?['Low stock','warning']:['In stock',''];
const badge=p=>{const [text,cls]=status(p);return `<span class="badge ${cls}">${text}</span>`;};
const heading=(title,sub,actions='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const metric=(label,value,ico,note,featured=false)=>`<div class="metric ${featured?'featured':''}"><div class="metric-top">${label}<span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;
const searchInput=(placeholder,value='',id='page-search')=>`<div class="search-input">${icon('search')}<input id="${id}" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(value)}" autocomplete="off"></div>`;
const table=(headers,rows,emptyText='No records to show.')=>rows.length?`<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty('Nothing here yet',emptyText);
const listFooter=(count)=>`<div class="panel-footer"><span>Showing ${Math.min(limit,count)} of ${count}</span>${count>limit?btn('Show more','more-records','down','compact'):''}</div>`;
function rangeDates(){const end=new Date();end.setHours(23,59,59,999);const start=new Date();start.setHours(0,0,0,0);if(range==='yesterday'){start.setDate(start.getDate()-1);end.setDate(end.getDate()-1);}else if(range==='month')start.setDate(1);else if(range==='custom'){return [new Date(customFrom+'T00:00:00').getTime(),new Date(customTo+'T23:59:59.999').getTime()];}else if(range!=='today')start.setDate(start.getDate()-(Number(range)-1));return [+start,+end];}
function inRange(date,a,b){const d=+new Date(date);return d>=a&&d<=b;}
function stats(a,b){const sales=data.sales.filter(s=>inRange(s.date,a,b)),returns=data.returns.filter(r=>inRange(r.date,a,b)),expenseTotal=data.expenses.filter(e=>inRange(e.date+'T00:00:00',a,b)).reduce((n,e)=>n+e.amount,0),grossProfit=sales.reduce((n,s)=>n+s.profit,0)-returns.reduce((n,r)=>n+r.profit,0);return {sales,returns,expenseTotal,grossProfit,revenue:sales.reduce((n,s)=>n+s.total,0)-returns.reduce((n,r)=>n+r.amount,0),net:sales.reduce((n,s)=>n+s.subtotal-s.discount+s.charges,0)-returns.reduce((n,r)=>n+r.net,0),cost:sales.reduce((n,s)=>n+s.cost,0)-returns.reduce((n,r)=>n+r.cost,0),profit:grossProfit-expenseTotal,units:DB.roundQty(sales.reduce((n,s)=>n+s.lines.reduce((x,l)=>x+l.qty,0),0)-returns.reduce((n,r)=>n+r.items.reduce((x,l)=>x+l.qty,0),0))};}
function rankings(st){const m=new Map();for(const s of st.sales)for(const l of s.lines){const v=m.get(l.productId)||{id:l.productId,name:l.name,qty:0,revenue:0,profit:0};v.qty+=l.qty;v.revenue+=l.total;v.profit+=l.profit;m.set(l.productId,v);}for(const r of st.returns)for(const l of r.items){const v=m.get(l.productId)||{id:l.productId,name:l.name,qty:0,revenue:0,profit:0};v.qty-=l.qty;v.revenue-=l.amount;v.profit-=l.profit;m.set(l.productId,v);}return [...m.values()].sort((a,b)=>b.qty-a.qty);}
function dateControl(){return `<select id="range" class="date-filter" aria-label="Report date range">${[['today','Today'],['yesterday','Yesterday'],['7','Last 7 days'],['30','Last 30 days'],['month','This month'],['custom','Custom range']].map(([v,l])=>`<option value="${v}" ${range===v?'selected':''}>${l}</option>`).join('')}</select>`;}
function customRange(){return range==='custom'?`<div class="toolbar date-custom"><label for="date-from">From</label><input type="date" id="date-from" value="${customFrom}"><label for="date-to">To</label><input type="date" id="date-to" value="${customTo}"></div>`:'';}
function lineChart(a,b){
 let n=Math.min(30,Math.max(1,Math.ceil((b-a)/86400000))),points=[];
 for(let i=0;i<n;i++){const from=a+(b-a+1)*i/n,to=a+(b-a+1)*(i+1)/n;const s=stats(from,to-(i<n-1?1:0));points.push({s,date:from});}
 const all=points.flatMap(p=>[p.s.revenue,p.s.profit]),max=Math.max(100,...all),min=Math.min(0,...all),span=max-min||1;
 const x=i=>54+i*596/Math.max(1,n-1),y=v=>180-(v-min)/span*145;
 const path=key=>points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p.s[key]).toFixed(1)}`).join(' ');
 const labels=[0,1,2,3].map(i=>{const v=min+span*i/3;return `<line x1="54" y1="${y(v)}" x2="650" y2="${y(v)}" class="chart-grid"/><text x="42" y="${y(v)+4}" text-anchor="end">${v>=100000?(v/100000).toFixed(1)+'k':Math.round(v/100)}</text>`;}).join('');
 const ticks=[...new Set([0,Math.floor((n-1)/3),Math.floor(2*(n-1)/3),n-1])].map(i=>`<text x="${x(i)}" y="208" text-anchor="middle">${fmtDate(points[i].date)}</text>`).join('');
 return `<svg class="chart" viewBox="0 0 680 220" role="img" aria-label="Sales and profit chart in ${esc(settings.currency)} for the selected period"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3a8d6b" stop-opacity=".17"/><stop offset="100%" stop-color="#3a8d6b" stop-opacity="0"/></linearGradient></defs>${labels}<path d="${path('revenue')} L${x(n-1)},${y(0)} L54,${y(0)}Z" fill="url(#area)"/><path d="${path('revenue')}" fill="none" stroke="#3a8d6b" stroke-width="2.7" stroke-linejoin="round"/><path d="${path('profit')}" fill="none" stroke="#a1bc66" stroke-width="2.2" stroke-linejoin="round"/>${ticks}</svg>`;
}
function salesRows(sales){return sales.map(s=>`<tr><td><button class="table-link" data-action="receipt" data-id="${s.id}"><strong>${esc(s.invoice)}</strong></button><div class="small muted">${fmtDate(s.date,true)}</div></td><td>${esc(s.customerName)}</td><td>${DB.roundQty(s.lines.reduce((n,l)=>n+l.qty,0))} items</td><td><span class="badge neutral">${esc(s.payment.method)}</span></td><td><strong>${money(s.total-s.refunded)}</strong>${s.refunded?'<div class="small muted">After refund</div>':''}</td><td>${iconBtn('View invoice','receipt','chevron',`data-id="${s.id}"`)}</td></tr>`);}
function shell(){
 const nav=[['dashboard','Overview','grid'],['pos','Point of sale','cart'],['products','Products','box'],['inventory','Inventory','stock'],['stock-in','Stock in','plus'],['sales','Sales & returns','receipt'],['expenses','Expenses','receipt'],['reports','Reports','chart'],['categories','Categories & brands','tag'],['full-version','Get full version','light']];
 $('#sidebar').innerHTML=`<a class="brand" href="#dashboard"><span class="brand-icon">${icon('store')}</span><span class="brand-text">Store<em>Flow</em><span style="font-size:10px;letter-spacing:1.5px;display:block;font-weight:550;color:var(--muted)">POINT OF SALE</span></span></a><div class="nav-section">WORKSPACE</div><nav>${nav.map(([r,l,i])=>`<a class="nav-link ${route===r?'active':''}" title="${l}" href="#${r}">${icon(i)}<span>${l}</span>${r==='inventory'&&lowProducts().length?`<span class="nav-count">${lowProducts().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#settings" title="Settings" class="nav-link ${route==='settings'?'active':''}">${icon('settings')}<span>Settings</span></a><div class="local-card"><strong>${icon('shield')} Ultra Storage</strong><p>Your site and business records live in the same Ultra Storage.</p></div></div>`;
 const title=nav.find(x=>x[0]===route)?.[1]||({movements:'Stock movements',settings:'Settings',more:'Your workspace'}[route]||'Overview');
 $('#topbar').innerHTML=`${iconBtn('Collapse sidebar','collapse','menu','class="collapse-btn"')}<span class="breadcrumb">${title}</span><button class="top-search" data-action="global-search" aria-label="Search products and invoices">${icon('search')}<span>Search your store…</span><kbd>/</kbd></button><div class="top-right">${btn(DB.repository.connected?'Ultra Storage connected':'Connect Ultra Storage','connect-repo','shield','compact repo-connect')}${iconBtn('Toggle theme','theme','moon')}<a href="#settings" class="shop-label"><strong>${esc(settings.name)}</strong><span>${demo?'Demo workspace':'Store owner'}</span></a><a href="#settings" class="avatar" aria-label="Store settings">${esc(settings.name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase())}</a></div>`;
 $('#topbar').firstElementChild.classList.add('collapse-btn');$('#topbar .top-right button').classList.add('theme-toggle');
 $('#mobile-nav').innerHTML=[['dashboard','Home','grid'],['pos','POS','cart'],['scan','Scan','scan'],['inventory','Stock','box'],['more','More','menu']].map(([r,l,i])=>r==='scan'?`<button class="scan-nav" data-action="scan-sell"><span>${icon(i)}</span>${l}</button>`:`<a href="#${r}" class="${route===r?'active':''}">${icon(i)}${l}</a>`).join('');
 $('#demo-banner').innerHTML=demo?`<div class="demo-banner"><span><strong>Demo workspace.</strong> Explore freely. Your real shop stays separate.</span>${btn('Exit demo','demo-exit','logout','ghost')}</div>`:'';
 document.body.classList.toggle('dark',(localStorage.getItem('storeflow-theme')||settings.theme)==='dark');
 document.body.classList.toggle('collapsed',localStorage.getItem('storeflow-collapsed')==='1');
 $('#connection').textContent=connectionText();document.title=`${title} · StoreFlow POS`;
}
function dashboard(){
 const dayStart=new Date();dayStart.setHours(0,0,0,0);const stToday=stats(+dayStart,Date.now()),[a,b]=rangeDates(),st=stats(a,b),ranks=rankings(st),recent=[...data.sales].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
 const hour=new Date().getHours(),greeting=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening';
 return heading(`${greeting}${settings.owner?', '+esc(settings.owner.split(' ')[0]):''} <span style="font-weight:400">☀</span>`,`Here’s what’s happening at ${esc(settings.name)}.`,dateControl()+btn('New sale','new-sale','plus','primary'))+customRange()+`<div class="metrics">${metric("Today's sales",money(stToday.revenue),'wallet',`${stToday.sales.length} completed orders`,true)}${metric("Today's net profit",money(stToday.profit),'trend',`${stToday.net?Math.round(stToday.profit/stToday.net*100):0}% estimated net margin`)}${metric("Today's orders",stToday.sales.length,'receipt',`${stToday.units} products sold today`)}${metric('Low stock',lowProducts().length,'alert',`<a href="#inventory" data-action="low-stock">${products().filter(p=>p.active&&p.stock<=0).length} out of stock · View inventory →</a>`)}</div>
 <div class="quick-actions">${[['new-sale','cart','New sale','Open the cashier'],['scan-sell','scan','Scan product','Point. Scan. Sell.'],['add-product','plus','Add product','Grow your inventory'],['stock-in','stock','Receive stock','Keep shelves ready']].map(([a,i,l,s])=>`<button class="quick-action" data-action="${a}"><span>${icon(i)}</span><div>${l}<small>${s}</small></div></button>`).join('')}</div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Sales overview</h2><p>A clear view of your store’s performance</p></div><div class="chart-legend"><span><i></i>Sales</span><span class="profit"><i></i>Profit</span></div></div><div class="chart-summary"><div><span class="chart-total">${money(st.revenue)}</span><div class="muted">Net sales for this period</div></div><span class="badge">${st.sales.length} orders</span></div><div class="panel-body" style="padding-top:18px;padding-bottom:8px">${lineChart(a,b)}</div></section>
 <section class="panel"><div class="panel-head"><div><h2>Top products</h2><p>Your customers’ favorites</p></div><a class="text-button" href="#reports">View all</a></div><div class="panel-body">${ranks.length?`<ol class="rank-list">${ranks.slice(0,4).map((r,i)=>`<li class="rank-row"><span class="rank-number">${i+1}</span>${thumb(product(r.id)||r)}<div><div class="rank-name">${esc(r.name)}</div><div class="rank-meta">${DB.roundQty(r.qty)} units sold</div></div><div class="rank-price">${money(r.revenue)}</div></li>`).join('')}</ol>`:empty('Your bestsellers go here','Complete your first sale to see which products your customers love.','','chart')}</div></section></div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Recent sales</h2><p>The latest from your counter</p></div><a href="#sales" class="text-button">View all ${icon('arrow')}</a></div>${table(['Invoice','Customer','Items','Payment','Amount',''],salesRows(recent),'Your first completed sale will appear here.')}</section><section class="panel"><div class="panel-head"><div><h2>Stock needs attention</h2><p>A little restock goes a long way</p></div><span class="badge warning">${lowProducts().length} products</span></div><div class="panel-body">${lowProducts().length?lowProducts().slice(0,4).map(p=>`<div class="low-stock-item">${thumb(p)}<div><button class="table-link" data-action="stock-form" data-id="${p.id}"><strong>${esc(p.name)}</strong></button><small>Minimum ${p.minStock} ${esc(p.unit)}</small></div><span class="badge ${p.stock<=0?'danger':'warning'}">${p.stock} left</span></div>`).join(''):empty('Shelves are looking good','Low-stock products will appear here.','','check')}</div></section></div>`;
}
function productFilters(){return `<div class="toolbar">${searchInput('Search name, barcode, SKU or brand…',filters.q||'')}<select id="category-filter" aria-label="Filter by category"><option value="">All categories</option>${[...new Set(products().map(p=>p.category))].sort().map(c=>`<option ${filters.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="brand-filter" aria-label="Filter by brand"><option value="">All brands</option>${[...new Set(products().map(p=>p.brand).filter(Boolean))].sort().map(c=>`<option ${filters.brand===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="status-filter" aria-label="Stock status">${['All statuses','In stock','Low stock','Out of stock','Expired','Inactive'].map((c,i)=>`<option value="${i?c:''}" ${filters.status===(i?c:'')?'selected':''}>${c}</option>`).join('')}</select><select id="sort-filter" aria-label="Sort products">${[['name','Name A–Z'],['stock','Stock: low first'],['price','Price: low first'],['profit','Profit: high first'],['category','Category'],['recent','Recently added']].map(([v,l])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function filteredProducts(){let ps=products().filter(p=>(!filters.q||searchProduct(p,filters.q))&&(!filters.category||p.category===filters.category)&&(!filters.brand||p.brand===filters.brand)&&(!filters.status||(filters.status==='Low stock'?p.active&&p.stock<=p.minStock:status(p)[0]===filters.status)));return ps.sort((a,b)=>filters.sort==='stock'?a.stock-b.stock:filters.sort==='price'?a.price-b.price:filters.sort==='profit'?(b.price-b.cost)-(a.price-a.cost):filters.sort==='recent'?b.created.localeCompare(a.created):filters.sort==='category'?a.category.localeCompare(b.category):a.name.localeCompare(b.name));}
function inventory(isInventory=false){
 const ps=filteredProducts(),all=products(),cost=all.reduce((n,p)=>n+Math.round(p.cost*p.stock),0),value=all.reduce((n,p)=>n+Math.round(p.price*p.stock),0);
 return heading(isInventory?'Inventory':'Products',isInventory?'Know what you have. Keep your bestsellers in stock.':'Everything on your shelves, in one place.',btn('Lookup','scan-lookup','scan')+btn('Import CSV','csv-import','upload')+btn('Add product','add-product','plus','primary'))+
 (isInventory?`<div class="metrics">${metric('Inventory value',money(cost),'box',`${all.length} products at purchase cost`,true)}${metric('Total stock units',DB.roundQty(all.reduce((n,p)=>n+p.stock,0)),'stock',`${all.filter(p=>p.stock<=0).length} products out of stock`)}${metric('Selling value',money(value),'wallet','Estimated at current prices')}${metric('Potential profit',money(value-cost),'trend',`${all.filter(p=>p.expiry&&p.expiry<DB.today()).length} expired products`)}</div><div class="page-subnav"><a class="active" href="#inventory">Stock overview</a><a href="#movements">Stock movements</a><a href="#stock-in">Receive stock</a></div>`:'')+
 productFilters()+`<div class="panel">${ps.length?table(['Product','Category','Purchase','Selling','Stock','Status','Actions'],ps.slice(0,limit).map(p=>`<tr><td><button class="table-link product-cell" data-action="product-detail" data-id="${p.id}">${thumb(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.sku||p.barcode||'No barcode')}</small></span></button></td><td>${esc(p.category)}</td><td>${money(p.cost)}</td><td>${money(p.price)}<div class="small muted">${profitPct(p)}% margin</div></td><td><strong>${p.stock}</strong> <span class="muted small">${esc(p.unit)}</span><div class="small muted">Min. ${p.minStock}</div></td><td>${badge(p)}</td><td><div class="actions">${iconBtn('Edit product','edit-product','edit',`data-id="${p.id}"`)}${iconBtn('Adjust stock','adjust-stock','stock',`data-id="${p.id}"`)}</div></td></tr>`)):empty('No products yet',all.length?'No products match these filters.':'Scan your first product or add one manually.',btn('Scan product','scan-add-mode','scan')+btn('Add product','add-product','plus','primary'))}${listFooter(ps.length)}</div><div class="actions" style="margin-top:18px">${btn('Export products','export-products','download')}${btn('Print barcode labels','labels','barcode')}</div>`;
}
function pos(){
 const ps=products().filter(p=>p.active&&(!filters.q||searchProduct(p,filters.q))&&(!filters.category||p.category===filters.category));
 return heading('Point of sale','A smooth checkout starts here.',btn(`Held bills${data.heldBills.length?' ('+data.heldBills.length+')':''}`,'held-bills','hold')+btn('Fast sell','fast-sell','light')+btn('Scan items','scan-sell','scan','primary'))+`<div class="pos-layout"><section><div class="toolbar">${searchInput('Search products or enter a barcode…',filters.q||'')}</div><div class="chips"><button class="chip ${!filters.category?'active':''}" data-action="pos-category" data-category="">All products</button>${[...new Set(products().map(p=>p.category))].map(c=>`<button class="chip ${filters.category===c?'active':''}" data-action="pos-category" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="pos-products">${ps.slice(0,limit).map(p=>`<button class="product-card" data-action="cart-add" data-id="${p.id}">${thumb(p)}<small>${esc(p.category)}</small><strong>${esc(p.name)}</strong><small>${p.stock} ${esc(p.unit)} available</small><div class="product-card-bottom">${money(p.price)}<span>${icon('plus')}</span></div></button>`).join('')}</div>${!ps.length?empty('Ready for your first product','Add products to start scanning and selling.',btn('Add product','add-product','plus','primary')):''}${ps.length>limit?listFooter(ps.length):''}</section><section class="panel cart" id="cart-panel">${cartMarkup()}</section></div>`;
}
function cartMarkup(){const t=currentTotals();return `<div class="cart-head"><h2>Current bill <span class="badge neutral">${cart.lines.length}</span></h2>${btn('Clear','cart-clear','','ghost compact')}</div><div class="cart-lines">${cart.lines.length?cart.lines.map(l=>{const p=product(l.productId),line=t.lines.find(x=>x.productId===l.productId);return `<div class="cart-line"><div class="cart-line-top"><strong>${esc(p?.name||'Unavailable product')}</strong><button class="table-link" aria-label="Remove ${esc(p?.name||'product')}" data-action="cart-remove" data-id="${l.productId}">${icon('close')}</button></div><div class="cart-line-bottom"><span>${money(p?.price||0)} / ${esc(p?.unit||'pcs')}</span><div class="qty-control" ${l.mode==='amount'?'hidden':''}><button aria-label="Decrease quantity" data-action="cart-minus" data-id="${l.productId}">−</button><input aria-label="Quantity for ${esc(p?.name)}" class="cart-qty" data-id="${l.productId}" type="number" min="0.001" step="0.001" value="${l.qty}"><button aria-label="Increase quantity" data-action="cart-plus" data-id="${l.productId}">+</button></div><strong>${money(line?.gross||0)}</strong></div>${p?.canAmount?`<div class="amount-editor"><label>Sell by <select class="cart-mode" data-id="${l.productId}" aria-label="Sell ${esc(p.name)} by"><option value="quantity" ${l.mode!=='amount'?'selected':''}>Quantity</option><option value="amount" ${l.mode==='amount'?'selected':''}>Amount (${esc(settings.symbol)})</option></select></label>${l.mode==='amount'?`<label>Amount <input type="number" class="cart-amount" data-id="${l.productId}" aria-label="Amount for ${esc(p.name)}" min="0.01" max="1000000000" step="0.01" value="${l.amount/100}" inputmode="decimal"></label><small>${line?.qty??l.qty} ${esc(p.unit)} · quantity rounded to 0.001 ${esc(p.unit)}. Amount kept exact before discounts and tax.</small>`:''}</div>`:''}</div>`;}).join(''):`<div class="cart-empty">${icon('cart')}<p style="margin:12px 0 0">Your bill is ready for its first item.</p><small>Tap a product or scan a barcode.</small></div>`}</div><div class="cart-settings"><details><summary class="small">Discount, tax & charges</summary><div class="form-grid" style="margin-top:12px"><div><label for="cart-discount">Discount</label><input type="number" id="cart-discount" min="0" step=".01" value="${cart.discountType==='percent'?cart.discount:cart.discount/100}"></div><div><label for="cart-discountType">Discount type</label><select id="cart-discountType"><option value="fixed" ${cart.discountType==='fixed'?'selected':''}>Fixed amount</option><option value="percent" ${cart.discountType==='percent'?'selected':''}>Percent</option></select></div><div><label for="cart-tax">Tax %</label><input type="number" id="cart-tax" min="0" max="100" step=".01" value="${cart.tax}"></div><div><label for="cart-charges">Charges</label><input type="number" id="cart-charges" min="0" step=".01" value="${cart.charges/100}"></div></div></details></div><div class="cart-summary"><div class="summary-row"><span class="muted">Subtotal</span><span>${money(t.subtotal)}</span></div>${t.discount?`<div class="summary-row"><span class="muted">Discount</span><span>− ${money(t.discount)}</span></div>`:''}${t.tax?`<div class="summary-row"><span class="muted">Tax (${cart.tax}%)</span><span>${money(t.tax)}</span></div>`:''}${t.charges?`<div class="summary-row"><span class="muted">Additional charges</span><span>${money(t.charges)}</span></div>`:''}<div class="summary-row total"><span>Total</span><span>${money(t.total)}</span></div><div class="actions">${btn('Hold bill','hold-bill','hold')}${btn('Checkout','checkout','arrow','primary',cart.lines.length?'style="flex:1"':'disabled style="flex:1"')}</div><p class="muted small" style="text-align:center;margin:13px 0 0">Stock updates when you complete the sale.</p></div>`;}
function stockIn(){return heading('Receive stock','Restock the shelf and keep a record of every delivery.',btn('Scan product','scan-stock','scan','primary'))+`<div class="page-subnav"><a href="#inventory">Stock overview</a><a href="#movements">Stock movements</a><a class="active" href="#stock-in">Receive stock</a></div><div class="toolbar">${searchInput('Find a product to receive…',filters.q||'')}</div><div class="panel">${table(['Product','Current stock','Purchase price','Selling price',''],filteredProducts().slice(0,limit).map(p=>`<tr><td><div class="product-cell">${thumb(p)}<span><strong>${esc(p.name)}</strong><small>${esc(p.barcode||p.sku||'No barcode')}</small></span></div></td><td>${p.stock} ${esc(p.unit)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td>${btn('Receive stock','stock-form','plus','',`data-id="${p.id}"`)}</td></tr>`),'Add a product or scan an unknown barcode to create one.')}${listFooter(filteredProducts().length)}</div>`;}
function movements(){const rows=[...data.movements].filter(m=>(!filters.q||[m.product,m.reason,m.reference,m.type].join(' ').toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.type||m.type===filters.type)).sort((a,b)=>b.date.localeCompare(a.date));return heading('Stock movements','Every change, with a reason and a reference.',btn('Export CSV','export-movements','download'))+`<div class="page-subnav"><a href="#inventory">Stock overview</a><a class="active" href="#movements">Stock movements</a><a href="#stock-in">Receive stock</a></div><div class="toolbar">${searchInput('Search product, reason or reference…',filters.q||'')}<select id="movement-filter" aria-label="Movement type"><option value="">All types</option>${['Opening Stock','Stock In','Sale','Return','Damaged','Adjustment','Import'].map(v=>`<option ${filters.type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="panel">${table(['Date','Product','Type','Before','Change','After','Reason / reference'],rows.slice(0,limit).map(m=>`<tr><td>${fmtDate(m.date,true)}</td><td>${esc(m.product)}</td><td><span class="badge neutral">${esc(m.type)}</span></td><td>${m.before}</td><td style="color:${m.change<0?'var(--red)':'var(--green)'}">${m.change>0?'+':''}${m.change}</td><td><strong>${m.after}</strong></td><td>${esc(m.reason)}<div class="small muted">${esc(m.reference)}</div></td></tr>`))}${listFooter(rows.length)}</div>`;}
function sales(){const rows=[...data.sales].filter(s=>(!filters.q||[s.invoice,s.customerName].join(' ').toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.payment||s.payment.method===filters.payment)&&(!filters.from||s.date>=new Date(filters.from+'T00:00:00').toISOString())&&(!filters.to||s.date<=new Date(filters.to+'T23:59:59.999').toISOString())).sort((a,b)=>b.date.localeCompare(a.date));return heading('Sales & returns','Every bill, every payment, every return.',btn('Export sales','export-sales','download')+btn('New sale','new-sale','plus','primary'))+`<div class="toolbar">${searchInput('Search invoice or customer…',filters.q||'')}<select id="payment-filter" aria-label="Payment method"><option value="">All payments</option>${['Cash','Card','Bank Transfer','Other'].map(v=>`<option ${filters.payment===v?'selected':''}>${v}</option>`).join('')}</select><input type="date" id="sales-from" aria-label="Sales from date" value="${filters.from||''}" style="width:auto"><input type="date" id="sales-to" aria-label="Sales to date" value="${filters.to||''}" style="width:auto"></div><div class="panel">${table(['Invoice','Customer','Items','Payment','Net amount',''],salesRows(rows.slice(0,limit)),'Completed sales will appear here. Open an invoice to print or return items.')}${listFooter(rows.length)}</div>`;}
function bars(map){const arr=[...map.entries()].sort((a,b)=>b[1]-a[1]),max=Math.max(1,...arr.map(x=>Math.abs(x[1])));return arr.length?`<div class="bars">${arr.map(([name,v])=>`<div><div class="bar-label"><span>${esc(name)}</span><strong>${money(v)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${Math.abs(v)/max*100}%"></div></div></div>`).join('')}</div>`:empty('No sales in this period','Choose another date range or complete your first sale.','','chart');}
function reports(){const [a,b]=rangeDates(),st=stats(a,b),ranks=rankings(st),categories=new Map(),payments=new Map();for(const s of st.sales){payments.set(s.payment.method,(payments.get(s.payment.method)||0)+s.total);for(const l of s.lines)categories.set(l.category,(categories.get(l.category)||0)+l.total);}for(const r of st.returns){payments.set(r.payment,(payments.get(r.payment)||0)-r.amount);for(const l of r.items)categories.set(l.category,(categories.get(l.category)||0)-l.amount);}return heading('Reports','Turn everyday sales into a clearer picture.',dateControl()+btn('Export sales','export-sales','download'))+customRange()+`<div class="metrics">${metric('Net sales',money(st.revenue),'wallet','Includes tax · less refunds',true)}${metric('Net profit',money(st.profit),'trend',`${st.net?(st.profit/st.net*100).toFixed(1):'0'}% margin · tax excluded`)}${metric('Cost of goods',money(st.cost),'box','Purchase cost saved at sale time')}${metric('Average bill',money(st.sales.length?Math.round(st.sales.reduce((n,s)=>n+s.total,0)/st.sales.length):0),'receipt',`${st.sales.length} orders · ${st.units} net units`)}</div><section class="panel" style="margin-bottom:22px"><div class="panel-head"><h2>Sales & profit over time</h2><div class="chart-legend"><span><i></i>Sales</span><span class="profit"><i></i>Profit</span></div></div><div class="panel-body">${lineChart(a,b)}</div></section><div class="report-grid"><section class="panel"><div class="panel-head"><h2>Sales by category</h2></div><div class="panel-body">${bars(categories)}</div></section><section class="panel"><div class="panel-head"><h2>Payment methods</h2></div><div class="panel-body">${bars(payments)}</div></section></div><div class="notice small">Sales profit after returns and discounts: ${money(st.grossProfit)} − expenses: ${money(st.expenseTotal)} = net profit: <strong>${money(st.profit)}</strong></div><section class="panel"><div class="panel-head"><h2>Best-selling products</h2><span class="badge neutral">${ranks.length} products</span></div>${table(['Product','Units sold','Net revenue','Estimated profit'],ranks.map(r=>`<tr><td>${esc(r.name)}</td><td>${DB.roundQty(r.qty)}</td><td>${money(r.revenue)}</td><td>${money(r.profit)}</td></tr>`))}</section><p class="small muted" style="margin-top:16px">Refunds reduce results on the return date. Profit includes discounts and charges, excludes tax, and deducts recorded expenses for the selected period. Restocking updates purchase cost for future sales.</p>`;}
function categories(){return heading('Categories & brands','A tidy catalog makes selling easier.',btn('Add brand','add-brand','plus')+btn('Add category','add-category','plus','primary'))+['categories','brands'].map(store=>`<section style="margin-bottom:26px"><h2 style="margin-bottom:15px">${store==='categories'?'Categories':'Brands'}</h2><div class="list-grid">${data[store].filter(c=>!filters.q||c.name.toLowerCase().includes(filters.q.toLowerCase())).map(c=>`<div class="panel list-card"><span class="metric-icon">${icon('tag')}</span><h3 style="margin:17px 0 6px">${esc(c.name)}</h3><div class="muted small">${products().filter(p=>p[store==='categories'?'category':'brand']===c.name).length} products</div><div class="actions">${btn('Edit','edit-taxonomy','edit','compact',`data-store="${store}" data-id="${c.id}"`)}${iconBtn('Delete','delete-taxonomy','trash',`data-store="${store}" data-id="${c.id}"`)}</div></div>`).join('')}</div>${!data[store].length?empty(`No ${store} yet`,'Organize your products so they are easier to find.','','tag'):''}</section>`).join('');}
function settingsPage(){return heading('Store settings','Make StoreFlow feel like your shop.')+`<div class="settings-layout"><form id="settings-form"><section class="panel settings-panel"><h2>Shop details</h2><div class="form-grid">${field('Shop name','name',settings.name,'text','required maxlength="100"')}${field('Owner name','owner',settings.owner,'text','maxlength="100"')}${field('Phone','phone',settings.phone,'tel')}${field('Email','email',settings.email,'email')}${field('Address','address',settings.address,'text','maxlength="250"',true)}<div class="field span-2"><label for="shop-logo">Shop logo</label><input type="file" id="shop-logo" name="logo" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG or WebP. Images are compressed and saved with your Ultra Storage records.</small>${settings.logo?`<img class="receipt-logo" src="${esc(settings.logo)}" alt="Shop logo">${checkField('Remove current logo','removeLogo',false)}`:''}</div></div></section><section class="panel settings-panel"><h2>Billing & inventory</h2><div class="form-grid">${field('Currency code','currency',settings.currency,'text','required minlength="3" maxlength="3"')}${field('Currency symbol','symbol',settings.symbol,'text','required maxlength="10"')}${field('Default tax (%)','tax',settings.tax,'number','min="0" max="100" step=".01" required')}${field('Default minimum stock','minStock',settings.minStock,'number','min="0" step=".001" required')}${field('Invoice prefix','prefix',settings.prefix,'text','required pattern="[A-Za-z0-9-]{1,12}" maxlength="12"')}${selectField('Theme','theme',['light','dark'],settings.theme)}${field('Receipt footer','footer',settings.footer,'text','maxlength="200"',true)}${checkField('Allow negative stock','negativeStock',settings.negativeStock)}${checkField('Scanner sound','sound',settings.sound)}${checkField('Scanner vibration','vibration',settings.vibration)}</div><p class="small muted" style="margin-top:16px">Changing currency changes the display label; it does not convert existing amounts. Tax applies after the bill discount, before additional charges.</p><div class="form-error" id="settings-error"></div><div class="dialog-actions"><button class="btn primary" type="submit">Save settings</button></div></section></form><section class="panel settings-panel"><h2>Backups & data</h2><div class="notice">Business records save automatically to the same Ultra Storage as this website. Connect the same Ultra Storage and branch on another device to open this store. Export a backup regularly.</div><div class="data-actions">${btn('Export complete backup','backup','download','primary')}${btn('Import complete backup','restore','upload')}${btn('Import old browser data','legacy-import','upload')}${btn('Products CSV','export-products','download')}${btn('Inventory CSV','export-products','download')}${btn('Sales CSV','export-sales','download')}${btn('Stock movements CSV','export-movements','download')}${btn('CSV import template','csv-template','download')}</div><p class="small muted" style="margin-top:15px">A backup contains your products, images, categories, brands, sales, returns, settings, stock ledger, saved bills and expenses. Restoring replaces the current workspace.</p></section><section class="panel settings-panel"><h2>App & account</h2><div class="actions">${btn('Install app','install','download')}${btn('How scanning works','scan-help','scan')}${btn(demo?'Clear demo data':'Explore demo shop',demo?'clear-demo':'demo-enter','grid')}</div><p class="small muted" style="margin-top:16px">An internet connection is required to confirm saves. Other connected devices check for updates every 30 seconds. Your Personal Access Key stays in this tab session only. Hold a bill to make it available to another cashier. Camera support depends on your browser and device.</p><div class="actions" style="margin-top:16px">${btn('Connect Ultra Storage','connect-repo','shield')}${btn('Refresh from Ultra Storage','repo-refresh','refresh')}${btn('Retry save','retry-save','upload')}${btn('Disconnect this tab','disconnect-repo','logout')}</div></section><section class="panel settings-panel"><h2>Reset options</h2><p class="muted small">Export a backup first. These actions cannot be undone without one.</p><div class="actions">${btn('Clear sales history','clear-sales','trash','danger')}${btn('Clear inventory','clear-inventory','trash','danger')}${btn('Reset application','reset','trash','danger')}</div></section></div>`;}
