async function labelsDialog(id){if(!products().length){toast('Add a product first.',true);return;}showDialog('Barcode labels',`<form id="labels-form"><div class="form-grid">${selectField('Product','productId',products().map(p=>[p.id,p.name]),id||products()[0].id,true)}${field('Number of labels','count',1,'number','required min="1" max="200" step="1"')}${checkField('Show price','price',true)}${checkField('Show shop name','shop',true)}${checkField('Show product name','productName',true)}${checkField('Show barcode value','displayValue',true)}</div><p class="muted small">An internal CODE-128 barcode is created if the product does not have one. Existing numeric or text values print as CODE-128 and scan to the same product.</p><div class="form-error"></div><div class="dialog-actions"><button class="btn primary" type="submit">Preview labels</button></div></form><div id="label-preview" style="margin-top:15px"></div>`);}
