  await DB.changeStock(id,qty,adjust?(v('reason')==='Damaged product'?'Damaged':'Adjustment'):'Stock In',reason,adjust?undefined:DB.cents(v('cost')));closeDialog();await refresh();toast(adjust?'Stock adjusted':'Stock increased');
