 if(el.id==='page-search'){clearTimeout(debounce);if(e.isComposing)return;debounce=setTimeout(()=>{if(!el.isConnected)return;filters.q=el.value;limit=40;const focused=document.activeElement===el,start=el.selectionStart,end=el.selectionEnd,direction=el.selectionDirection,marker=document.createComment('search');el.replaceWith(marker);render();const replacement=$('#page-search');if(replacement){replacement.replaceWith(el);if(focused){el.focus();el.setSelectionRange(start,end,direction);}}},150);}
