 const el=e.target;features.change(el);if(el.classList.contains('cart-qty')||el.classList.contains('cart-mode')||el.classList.contains('cart-amount')||el.id.startsWith('cart-'))DB.repository.require();const mappings={'category-filter':'category','brand-filter':'brand','status-filter':'status','sort-filter':'sort','payment-filter':'payment','sales-from':'from','sales-to':'to','movement-filter':'type'};
