async function action(a,id,el){
 if(a==='connect-repo'){if(draftDirty&&!DB.repository.journal())await saveDraft();connectionDialog(DB.repository.journal()?'Reconnect the same Ultra Storage to recover your pending save.':'');return;}
 if(a==='retry-save'){await DB.retrySave();await reload();if(data.sales.some(s=>s.id===cart.id)){cart=DB.newCart(settings.tax);draftDirty=false;}if(draftDirty)await saveDraft();await refresh();toast('Save confirmed in Ultra Storage');return;}
 if(a==='repo-refresh'){await refresh();toast('Latest records loaded');return;}
 if(a==='disconnect-repo'){if(draftDirty)await saveDraft();DB.repository.disconnect();cart=DB.newCart();await DB.openDB(demo);await refresh();return;}
 const writes=['add-product','edit-product','stock-form','adjust-stock','scan-sell','fast-sell','scan-stock','scan-add-mode','onboard-product','cart-add','cart-plus','cart-minus','cart-remove','cart-clear','checkout','return-form','hold-bill','resume-bill','recover-draft','delete-held','add-category','add-brand','edit-taxonomy','delete-taxonomy','delete-product','restore','legacy-import','csv-import','csv-choose','csv-confirm','demo-enter','demo-exit','clear-demo','clear-sales','clear-inventory','reset','theme','fx-expense','fx-delete-expense'];
 if(writes.includes(a))DB.repository.require();
 if(await features.action(a,id))return;
 if(a==='close')closeDialog();
 else if(a==='collapse'){localStorage.setItem('storeflow-collapsed',document.body.classList.contains('collapsed')?'0':'1');shell();}

 else if(a==='theme'){const theme=document.body.classList.contains('dark')?'light':'dark';await DB.saveSettings({...settings,theme},settings);localStorage.setItem('storeflow-theme',theme);await refresh();}
 else if(a==='global-search')globalSearch();
 else if(a==='new-sale'){closeDialog();navigate('pos');}
 else if(a==='add-product')productForm();
 else if(a==='edit-product')productForm(id);
 else if(a==='product-detail')productDetail(id);
 else if(a==='stock-in')navigate('stock-in');
 else if(a==='stock-form')stockForm(id);
 else if(a==='adjust-stock')stockForm(id,true);
 else if(a==='scan-sell'||a==='fast-sell'){closeDialog();if(route!=='pos')navigate('pos');scan('sell',a==='fast-sell');}
 else if(a==='scan-stock')scan('stock');
 else if(a==='scan-add-mode')scan('add');
 else if(a==='scan-lookup')scan('lookup');
 else if(a==='scan-help')scanHelp();
 else if(a==='onboard-next')onboarding(3);
 else if(a==='onboard-product')productForm(null,'',()=>onboarding(3));
 else if(a==='cart-add'){addToCart(id);toast('Product added to bill');}
 else if(a==='cart-plus')addToCart(id);
 else if(a==='cart-minus'){const l=cart.lines.find(l=>l.productId===id);if(l.qty<=1)cart.lines=cart.lines.filter(l=>l.productId!==id);else l.qty=DB.roundQty(l.qty-1);delete l.mode;delete l.amount;cartChanged();}
 else if(a==='cart-remove'){cart.lines=cart.lines.filter(l=>l.productId!==id);cartChanged();}
 else if(a==='cart-clear'){if(cart.lines.length)confirmAction('Clear current bill?','This removes the current bill. Your inventory will not change.',async()=>{cart=DB.newCart(settings.tax);await saveDraft();render();},'CLEAR');}
 else if(a==='pos-category'){filters.category=el.dataset.category;limit=40;render();}
 else if(a==='checkout')checkoutForm();
 else if(a==='receipt')receipt(id);
 else if(a==='return-form')returnForm(id);
 else if(a==='print-receipt'||a==='print-58'||a==='print-80'){const s=data.sales.find(s=>s.id===id);printContent(receiptMarkup(s),a==='print-receipt'?null:a.slice(-2));}
 else if(a==='hold-bill'){
  if(!cart.lines.length)throw new Error('Add a product before holding this bill.');clearTimeout(draftTimer);await DB.atomic(['heldBills','settings'],async s=>{await DB.req(s.heldBills.put({...structuredClone(cart),date:new Date().toISOString(),total:currentTotals().total}));await DB.req(s.settings.delete(DB.draftId));});cart=DB.newCart(settings.tax);draftDirty=false;await refresh();toast('Bill held');
 }else if(a==='held-bills')heldBills();
 else if(a==='resume-bill'){
  if(cart.lines.length)throw new Error('Hold or clear the current bill before resuming another.');const h=data.heldBills.find(h=>h.id===id);if(!h)throw new Error('This held bill is no longer available.');let resumed;await DB.atomic(['heldBills','settings'],async s=>{const current=await DB.req(s.heldBills.get(id));if(!current)throw new Error('This bill was already opened on another device.');resumed={...current,heldId:id};await DB.req(s.settings.put({id:DB.draftId,cart:structuredClone(resumed)}));await DB.req(s.heldBills.delete(id));});cart=resumed;closeDialog();await refresh();navigate('pos');toast('Bill restored. Prices and availability use the current catalog.');
 }else if(a==='recover-draft'){await DB.atomic(['settings','heldBills','sales'],async s=>{const draft=await DB.req(s.settings.get(id));if(!draft?.cart?.lines?.length)throw new Error('This saved bill is no longer available.');if(await DB.req(s.sales.get(draft.cart.id)))throw new Error('This bill has already been completed.');await DB.req(s.heldBills.put({...draft.cart,date:new Date().toISOString()}));await DB.req(s.settings.delete(id));});await reload();heldBills();toast('Bill recovered. Resume it from Held bills.');
 }else if(a==='delete-held')confirmAction('Delete held bill?','The saved bill will be removed. Stock is unchanged.',async()=>{await DB.remove('heldBills',id);await refresh();heldBills();});
 else if(a==='low-stock'){filters={status:'Low stock'};route='inventory';location.hash='inventory';render();}
 else if(a==='more-records'){limit+=40;render();}
 else if(a==='add-category')taxonomyForm('categories');
 else if(a==='add-brand')taxonomyForm('brands');
 else if(a==='edit-taxonomy')taxonomyForm(el.dataset.store,id);
 else if(a==='delete-taxonomy'){
  const store=el.dataset.store,c=data[store].find(c=>c.id===id);confirmAction(`Delete ${store==='categories'?'category':'brand'}?`,`${esc(c.name)} will be removed. Products will ${store==='categories'?'move to Uncategorized':'have no brand'}.`,async()=>{await DB.atomic([store,'products'],async s=>{await DB.req(s[store].delete(id));for(const p of await DB.req(s.products.getAll())){const key=store==='categories'?'category':'brand';if(p[key]===c.name){p[key]=store==='categories'?'Uncategorized':'';await DB.req(s.products.put(p));}}});await refresh();toast('Removed');});
 } else if(a==='delete-product')confirmAction('Delete product?',`This product will leave your catalog. Historical sales and stock records are retained.`,async()=>{await DB.atomic(['products'],async s=>{const p=await DB.req(s.products.get(id));p.deleted=true;p.active=false;p.image='';p.updated=new Date().toISOString();await DB.req(s.products.put(p));});cart.lines=cart.lines.filter(l=>l.productId!==id);await saveDraft();await refresh();toast('Product deleted');});
 else if(a==='generate-code'){const code='SF-'+DB.uid().replaceAll('-','').slice(0,12).toUpperCase();$('#f-barcode').value=code;$('#f-sku').value=code;}
 else if(a==='backup')await backup();
 else if(a==='legacy-import'){const b=await readLegacyBrowserBackup();confirmAction('Move old browser data to Ultra Storage?',`${b.data.products.length} products and ${b.data.sales.length} sales found in the original browser store. This replaces the connected Ultra Storage workspace. Customer profiles are excluded. The old browser copy stays unchanged. Export the current Ultra Storage backup first.`,async()=>{await restoreBackup(b);await reload();cart=data.settings.find(s=>s.id===DB.draftId)?.cart||DB.newCart(settings.tax);draftDirty=false;render();toast('Old browser data saved to Ultra Storage');},'IMPORT');}
 else if(a==='restore')chooseFile('.json,application/json',async file=>{if(file.size>100*1024*1024)throw new Error('Backup exceeds the 100 MB import limit.');let b;try{b=JSON.parse(await file.text());}catch{throw new Error('The backup is not valid JSON.');}pendingBackup=validateBackup(b);confirmAction('Restore complete backup?',`Backup created ${fmtDate(b.exportedAt,true)} · version ${esc(b.appVersion)}.<br>${b.data.products.length} products, ${b.data.sales.length} sales, ${b.data.expenses.length} expenses.<br><strong>All data in this ${demo?'demo':'real'} workspace will be replaced.</strong> Export your current backup first.`,async()=>{await restoreBackup(pendingBackup);pendingBackup=null;await reload();cart=data.settings.find(s=>s.id===DB.draftId)?.cart||DB.newCart(settings.tax);render();channel?.postMessage({demo});toast('Backup restored');},'RESTORE');});
 else if(a.startsWith('export-'))exportCSV(a.slice(7));
 else if(a==='csv-template')download('storeflow-products-template.csv',csvExport([['Name','Barcode','SKU','Category','Brand','Purchase Price','Selling Price','Stock','Minimum Stock','Unit','Allow sell by amount'],['Example product','SF-0001','SKU-0001','Groceries','Example',100,130,20,5,'pcs','no']]),'text/csv;charset=utf-8');
 else if(a==='csv-import')csvImportDialog();
 else if(a==='csv-choose')chooseFile('.csv,text/csv',async file=>{if(file.size>10*1024*1024)throw new Error('Choose a CSV smaller than 10 MB.');importRows=previewCSV(await file.text(),data.products);csvPreview(importRows);});
 else if(a==='csv-confirm'){if(!importRows.length)throw new Error('Choose a CSV file first.');await importCSV(importRows);const count=importRows.length;importRows=[];closeDialog();await refresh();toast(`${count} products imported`);}
 else if(a==='labels')await labelsDialog(id);
 else if(a==='print-labels')printContent($('#labels-ready').outerHTML);
 else if(a==='demo-enter')await switchDemo(true);
 else if(a==='demo-exit')await switchDemo(false);
 else if(a==='clear-demo')confirmAction('Clear demo data?','This clears only the demo workspace. Your real shop is not changed.',async()=>{await DB.atomic(DB.STORES,async s=>{for(const n of DB.STORES)await DB.req(s[n].clear());});cart=DB.newCart();await switchDemo(false);},'CLEAR');
 else if(a==='install'){if(installEvent){await installEvent.prompt();await installEvent.userChoice;installEvent=null;}else showDialog('Install StoreFlow',`<div class="feature-list"><div>${icon('download')}<span><strong>Android / Chrome:</strong> Open the browser menu and choose Install app or Add to Home screen.</span></div><div>${icon('download')}<span><strong>iPhone / Safari:</strong> Tap Share, then Add to Home Screen.</span></div><div>${icon('info')}<span>If already installed, open StoreFlow from your home screen. Installation is available after the site is served over HTTPS.</span></div></div>`);}
 else if(a==='clear-sales')confirmAction('Clear sales history?',`Sales, returns and their stock ledger entries will be removed. Current stock quantities remain unchanged, with a new ledger baseline. Export a backup first.`,async()=>{await DB.atomic(['sales','returns','movements','products'],async s=>{await DB.req(s.sales.clear());await DB.req(s.returns.clear());await DB.req(s.movements.clear());for(const p of await DB.req(s.products.getAll()))await DB.req(s.movements.add(DB.movement(p,0,p.stock,'Adjustment','Baseline after clearing sales history')));});await refresh();toast('Sales history cleared');},'CLEAR');
 else if(a==='clear-inventory')confirmAction('Clear inventory?',`All products, categories and brands will leave the catalog. Referenced products remain archived for invoices and returns. Current and held bills will be cleared.  Export a backup first.`,async()=>{await DB.atomic(['products','categories','brands','heldBills','settings','movements'],async s=>{for(const p of await DB.req(s.products.getAll())){if(p.stock)await DB.req(s.movements.add(DB.movement(p,p.stock,-p.stock,'Adjustment','Inventory cleared')));p.stock=0;p.deleted=true;p.active=false;p.image='';await DB.req(s.products.put(p));}for(const n of ['categories','brands','heldBills'])await DB.req(s[n].clear());for(const setting of await DB.req(s.settings.getAll()))if(setting.id==='draft'||setting.id.startsWith('draft:'))await DB.req(s.settings.delete(setting.id));});cart=DB.newCart(settings.tax);await refresh();toast('Inventory cleared');},'CLEAR');
 else if(a==='reset')confirmAction('Reset application?',`Every record in this ${demo?'demo':'real'} workspace will be deleted. This includes products, sales, settings and expenses. Export a backup before continuing.`,async()=>{await DB.atomic(DB.STORES,async s=>{for(const n of DB.STORES)await DB.req(s[n].clear());});cart=DB.newCart();await reload();render();onboarding();},'RESET');
}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;if(['scan-close','scan-ignore','scan-add','scan-checkout','torch'].includes(a))return;e.preventDefault();if(busy)return;busy=true;try{await action(a,el.dataset.id,el);}catch(err){toast(safeError(err),true);}finally{busy=false;}});
