  if(e.key==='Enter'&&e.target.id==='page-search'){const code=e.target.value.trim(),p=products().find(p=>p.barcode===code||p.sku===code);if(p){e.preventDefault();clearTimeout(debounce);try{addToCart(p.id);filters.q='';render();$('#page-search')?.focus();toast('Product added to bill');}catch(err){toast(err.message,true);}}}
