function registerTools(){
 if(!document.modelContext?.registerTool)return;
 const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});
 const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});}catch{}};
 register({name:'search_store_products',description:'Read shared product availability and prices matching a name, barcode or SKU.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:({query})=>{if(typeof query!=='string'||query.length>200)throw new Error('Provide a query up to 200 characters.');return products().filter(p=>searchProduct(p,query)).slice(0,30).map(p=>({id:p.id,name:p.name,barcode:p.barcode,stock:p.stock,price:p.price/100,currency:settings.currency}));}});
 register({name:'stage_products_in_bill',description:'Add products to the current bill and open the cashier. Does not complete payment or deduct stock.',inputSchema:{type:'object',properties:{items:{type:'array',minItems:1,maxItems:50,items:{type:'object',properties:{productId:{type:'string'},quantity:{type:'number',exclusiveMinimum:0}},required:['productId','quantity'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async({items})=>{DB.repository.require();if(!Array.isArray(items)||!items.length||items.length>50)throw new Error('Provide 1 to 50 items.');const before=structuredClone(cart);try{for(const i of items){if(typeof i.productId!=='string')throw new Error('Invalid product ID.');DB.number(i.quantity,'Quantity',.001);const p=product(i.productId),old=cart.lines.find(l=>l.productId===i.productId),q=DB.roundQty((old?.qty||0)+i.quantity);if(!p||p.deleted||!p.active||(!settings.negativeStock&&p.stock<q))throw new Error('Product unavailable or insufficient stock.');if(old){old.qty=q;delete old.mode;delete old.amount;}else cart.lines.push({productId:p.id,qty:q});}await saveDraft();navigate('pos');return {lines:cart.lines.length,total:currentTotals().total/100,currency:settings.currency};}catch(e){cart=before;throw e;}}});
}
async function start(){
 try{initConnectionUI(async()=>{demo=false;sessionStorage.setItem('storeflow-github-demo','0');await DB.openDB(false);await reload();cart=data.settings.find(s=>s.id===DB.draftId)?.cart||DB.newCart(settings.tax);draftDirty=false;render();if(!settings.onboarded)onboarding();});try{if(await DB.repository.restore())await DB.retrySave();}catch(e){toast(safeError(e),true);}await DB.openDB(demo);if(demo&&DB.repository.connected)await seedDemo();await reload();cart=data.settings.find(s=>s.id===DB.draftId)?.cart||DB.newCart(settings.tax);route=location.hash.slice(1).split('?')[0]||'dashboard';render();if(!settings.onboarded&&!demo&&DB.repository.connected)onboarding();registerTools();}
 catch(error){$('#main').innerHTML=empty('Your store is temporarily unavailable',esc(safeError(error)),btn('Reload','reload','refresh'),'alert');document.querySelector('[data-action="reload"]').onclick=()=>location.reload();}
}
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
if(location.protocol!=='file:')start();

window.addEventListener('beforeunload',e=>{if(draftDirty||DB.repository.pending){e.preventDefault();e.returnValue='';}});

document.addEventListener('compositionend',e=>{if(e.target.id==='page-search')e.target.dispatchEvent(new Event('input',{bubbles:true}));});
